<?php
namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class Json{public static function cors(){header('Access-Control-Allow-Origin: *');header('Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS');header('Access-Control-Allow-Headers: Content-Type, Accept, Authorization, X-Api-Token, X-Admin-Token');if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(204);exit;}}public static function send($a,$b=200){$c=json_encode($a,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if($c===false){$b=500;$c='{"success":false,"error":"response encoding failed"}';}http_response_code($b);header('Content-Type: application/json; charset=utf-8');echo $c;exit;}public static function error($a,$b,array $c=[]){self::send(array_merge(['success'=>false,'error'=>$b],$c),$a);}public static function ok($a=null){self::send(['success'=>true,'data'=>$a]);}}